html:
{%- set sig -%}
{%- if doc.workflow_state == 'Approved' and doc.approver_signature -%}
<img src="{{ doc.approver_signature }}" alt="Authorised Signatory" style="height:50px;object-fit:contain;display:block;margin-bottom:4px;" />
<div style="font-size:10px;color:#374151;margin-top:4px;">Approved by {{ doc.approver_name or 'Head of Section' }}{% if doc.approver_date %} on {{ frappe.utils.formatdate(doc.approver_date, "dd.MM.yyyy") }}{% endif %}</div>
{%- else -%}
<div style="font-style:italic;color:#6b7280;font-size:10px;">(Signature to be affixed after approval by the Head of Section, R&amp;D)</div>
{%- endif -%}
{%- endset -%}
<div class="print-format-content">
{{ (doc.invoice_content or "") | replace("<!--SIGNATURE_SLOT-->", sig) }}
</div>
